llm_schema_prompt.sql:
SELECT DISTINCT me.entry_id, me.formula, me.reduced_formula, me.chemical_system
FROM material_entry me
WHERE EXISTS (
    SELECT 1 FROM composition c WHERE c.entry_id = me.entry_id AND c.element = 'H'
) AND EXISTS (
    SELECT 1 FROM composition c WHERE c.entry_id = me.entry_id AND c.element = 'Fe'
) AND EXISTS (
    SELECT 1 FROM composition c WHERE c.entry_id = me.entry_id AND c.element = 'Ni'
) AND EXISTS (
    SELECT 1 FROM composition c WHERE c.entry_id = me.entry_id AND c.element = 'Co'
) AND EXISTS (
    SELECT 1 FROM phase_stability ps WHERE ps.entry_id = me.entry_id AND ps.energy_above_hull <= 0.001
)
LIMIT 100;

